import tiktoken

enc = tiktoken.encoding_for_model('deepseek-v4-pro')

def count_tokens(text: str) -> int:
    return len(enc.encode(text))

def count_messages_tokens(messages: list) -> int:
    total = 0
    for msg in messages:
        total += 4 + count_tokens(msg['content'])
    return total

messages = [{'role':'system','content':'你是助手'*100}, {'role':'user','content':'你好'*50}]
tokens = count_messages_tokens(messages)
print(f'总 token: {tokens}')
print(f'预算 4096, {"超限" if tokens > 4096 else "OK"}')

import tiktoken
enc = tiktoken.encoding_for_model('deepseek-v4-pro')

def count_tokens(messages):
    return sum(4 + len(enc.encode(m['content'])) for m in messages)

def trim_messages(messages, max_tokens=4096):
    while count_tokens(messages) > max_tokens and len(messages) > 1:
        for i in range(1, len(messages)):
            if messages[i]['role'] != 'system':
                messages.pop(i)
                break
        else:
            break
    return messages

messages = [{'role':'system','content':'你是助手'}]
for i in range(20):
    messages.append({'role':'user','content':f'第{i}条消息'*10})
    messages.append({'role':'assistant','content':f'回复{i}'*10})

print(f'截断前: {count_tokens(messages)} tokens, {len(messages)} 条')
messages = trim_messages(messages, 500)
print(f'截断后: {count_tokens(messages)} tokens, {len(messages)} 条')
